/*
 * A232798  Sequence (or tree) generated by these rules: 1 is in S, and if x
 *          is in S, then x + 1, 3*x - 1 and 3*x + 1 are in S, and duplicates
 *          are deleted as they occur.
 * https://oeis.org/A232798
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = permutation of positive integers generated by S = {1};
 *            for each x in S, add x+1, 3x-1, 3x+1 if not already in S
 * Range:     u8 n <= 98, u16 n <= 4000, u32 n <= 4000, u64 n <= 4000,
 *            u128 n <= 4000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* seq_t and idx_t are provided by the build environment. */
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* Return 0 for non‑positive index (not used by OEIS). */
    if (n == 0) return (seq_t)0;

    static seq_t *S = NULL;          /* sequence array */
    static size_t sz = 0;            /* number of elements in S   */
    static size_t cap = 0;           /* allocated capacity of S    */
    static bool init = false;        /* one‑time initialization */

    /* Ensure S is initialized. */
    if (!init) {
        cap = 2048;                   /* initial capacity – more than enough for n <= 10000 */
        S = (seq_t *)malloc(cap * sizeof(seq_t));
        if (!S) return (seq_t)0;     /* out of memory */
        S[0] = (seq_t)1;             /* first element */
        sz = 1;
        init = true;
    }

    /* Generate further terms until we have at least n of them. */
    size_t idx = 0;
    while (sz < (size_t)n) {
        if (idx >= sz) break;        /* safety, should not happen */
        seq_t x = S[idx++];
        /* Candidate 1: x + 1 */
        seq_t c = x + 1;
        bool dup = false;
        for (size_t i = 0; i < sz; ++i) {
            if (S[i] == c) { dup = true; break; }
        }
        if (!dup) {
            if (sz == cap) {
                cap *= 2;
                S = (seq_t *)realloc(S, cap * sizeof(seq_t));
                if (!S) return (seq_t)0;
            }
            S[sz++] = c;
            if (sz == (size_t)n) break;
        }
        /* Candidate 2: 3*x - 1 */
        c = 3 * x - 1;
        dup = false;
        for (size_t i = 0; i < sz; ++i) {
            if (S[i] == c) { dup = true; break; }
        }
        if (!dup) {
            if (sz == cap) {
                cap *= 2;
                S = (seq_t *)realloc(S, cap * sizeof(seq_t));
                if (!S) return (seq_t)0;
            }
            S[sz++] = c;
            if (sz == (size_t)n) break;
        }
        /* Candidate 3: 3*x + 1 */
        c = 3 * x + 1;
        dup = false;
        for (size_t i = 0; i < sz; ++i) {
            if (S[i] == c) { dup = true; break; }
        }
        if (!dup) {
            if (sz == cap) {
                cap *= 2;
                S = (seq_t *)realloc(S, cap * sizeof(seq_t));
                if (!S) return (seq_t)0;
            }
            S[sz++] = c;
            if (sz == (size_t)n) break;
        }
    }

    return S[n - 1];
}
